/// <summary>
/// Inserts entity data source.
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext.</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext.</param>
/// <returns>Boolean</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(GUPPriceTermJournalTransEntity, GUPPriceTermJournalTrans))
    {
        GUPPriceTermJournalTrans priceTermJrnlTrans = _dataSourceCtx.getBuffer();

        priceTermJrnlTrans.LineNum = GUPPriceTermJournalTrans::lastLineNum(priceTermJrnlTrans.AgreementId) + 1;
    }

    ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

    return ret;
}
